const header = generatedAt => `// Auto-generated file - DO NOT EDIT MANUALLY
// This file is generated by: npx blog-engine process
// Generated at: ${generatedAt}
`;

const postsModule = (posts, generatedAt) => `${header(generatedAt)}
export const posts = ${JSON.stringify(posts, null, 2)};

export const getPostBySlug = (slug) => posts.find(post => post.slug === slug);

export const getPostsByCategory = (category) => (
  posts.filter(post => post.category.toLowerCase() === category.toLowerCase())
);

export const getAllCategories = () => Array.from(new Set(posts.map(post => post.category)));

export const getAllTags = () => Array.from(new Set(posts.flatMap(post => post.tags)));

export const getPostsByTag = (tag) => posts.filter(post => post.tags.includes(tag));
`;

const pagesModule = (pages, generatedAt) => `${header(generatedAt)}
export const pages = ${JSON.stringify(pages, null, 2)};

export const getPageBySlug = (slug) => pages.find(page => page.slug === slug);
`;

const metadataModule = (pages, generatedAt) => `${header(generatedAt)}
export const pages = ${JSON.stringify(
    pages.map(({ slug, title, order }) => ({ slug, title, order })),
    null,
    2,
  )};
`;

export const createGeneratedModules = (posts, pages, generatedAt = new Date().toISOString()) => ({
  'content/posts.js': postsModule(posts, generatedAt),
  'content/pages.js': pagesModule(pages, generatedAt),
  'content/metadata.js': metadataModule(pages, generatedAt),
});
